// Bundles react, react-dom, tendril-wireframes and their transitive deps into a set of
// ESM entry points that the browser resolves through an import map at runtime.
//
// CRITICAL: this is ONE esbuild invocation with many entry points and splitting:true.
// Building each entry separately would give each output its own copy of React's module
// state (ReactSharedInternals, the hook dispatcher) -> "Invalid hook call", and
// SketchProvider's context would be invisible to the widgets beneath it.
import * as esbuild from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { generateFacades } from "./gen-facades.mjs";

const require = createRequire(import.meta.url);
const here = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
const entriesDir = path.join(here, ".entries");
const outDir = path.resolve(here, "../../artifacts/vendor");

/** Reads a dependency's version from disk. Some packages (tendril-wireframes) do not
 *  expose "./package.json" in their exports map, so require() cannot reach it. */
const pkgVersion = (name) =>
  JSON.parse(fs.readFileSync(path.join(here, "node_modules", name, "package.json"), "utf8")).version;

/** Packages that are already ESM with static named exports -- `export *` is safe. */
const ESM_REEXPORTS = ["tendril-wireframes", "lucide-react"];

/** Maps an import-map specifier to the entry file name esbuild will emit. */
const entryName = (spec) => spec.replace(/[/@]/g, "__");

export async function buildVendor({ minify = true } = {}) {
  fs.rmSync(entriesDir, { recursive: true, force: true });
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(entriesDir, { recursive: true });
  fs.mkdirSync(outDir, { recursive: true });

  // CJS packages need enumerated named exports (see gen-facades.mjs).
  const facades = generateFacades(entriesDir);
  const specifiers = Object.keys(facades);

  // ESM packages can be re-exported wholesale and stay statically analyzable.
  for (const spec of ESM_REEXPORTS) {
    const file = path.join(entriesDir, entryName(spec) + ".js");
    fs.writeFileSync(
      file,
      `// GENERATED by build-vendor.mjs -- do not edit.\n` +
        `export * from ${JSON.stringify(spec)};\n`
    );
    specifiers.push(spec);
  }

  const entryPoints = Object.fromEntries(
    specifiers.map((spec) => [entryName(spec), path.join(entriesDir, entryName(spec) + ".js")])
  );

  const result = await esbuild.build({
    entryPoints,
    outdir: outDir,
    bundle: true,
    splitting: true, // shared code -> chunk-*.js, so there is exactly one React instance
    format: "esm",
    platform: "browser",
    // Without this esbuild picks lucide-react's "node" condition and pulls in its CJS build.
    conditions: ["browser", "import", "module", "default"],
    target: ["es2022"],
    minify,
    legalComments: "none",
    sourcemap: false,
    metafile: true,
    entryNames: "[name]",
    chunkNames: "chunk-[hash]",
    define: {
      // React branches on this; production also drops its dev-only warning machinery.
      "process.env.NODE_ENV": '"production"',
    },
    // Stray deps sometimes touch bare `process`. The harness also defines this, but a
    // banner keeps the vendor bundle self-sufficient if it is ever loaded standalone.
    banner: {
      js: "globalThis.process ??= { env: { NODE_ENV: 'production' } };",
    },
  });

  // Read the output directory rather than the metafile: metafile keys are relative to
  // the process CWD, which makes them fragile depending on where this script is run from.
  const outputs = fs.readdirSync(outDir).filter((f) => f.endsWith(".js"));
  void result;

  const manifest = {
    generated: "Do not edit. Produced by build/vendor/build-vendor.mjs.",
    versions: Object.fromEntries(
      ["react", "react-dom", "tendril-wireframes", "lucide-react", "esbuild"].map((n) => [
        n,
        pkgVersion(n),
      ])
    ),
    // Single source of truth for BOTH the esbuild --external: list and the browser
    // import map. Keeping these in one place is what stops them drifting apart.
    specifiers: Object.fromEntries(
      specifiers.map((spec) => [spec, `/__wireframe/vendor/${entryName(spec)}.js`])
    ),
    chunks: outputs.filter((f) => f.startsWith("chunk-")).sort(),
    entries: outputs.filter((f) => !f.startsWith("chunk-")).sort(),
  };

  fs.writeFileSync(
    path.resolve(outDir, "../vendor.manifest.json"),
    JSON.stringify(manifest, null, 2) + "\n"
  );

  const sizes = outputs
    .map((f) => ({ f, bytes: fs.statSync(path.join(outDir, f)).size }))
    .sort((a, b) => b.bytes - a.bytes);
  const total = sizes.reduce((n, s) => n + s.bytes, 0);

  return { manifest, sizes, total };
}

if (import.meta.url === (await import("node:url")).pathToFileURL(process.argv[1]).href) {
  const { manifest, sizes, total } = await buildVendor();
  for (const { f, bytes } of sizes) {
    console.log(`  ${(bytes / 1024).toFixed(1).padStart(9)} KB  ${f}`);
  }
  console.log(`  ${"-".repeat(9)}`);
  console.log(`  ${(total / 1024 / 1024).toFixed(2).padStart(9)} MB  total`);
  console.log("\nimport map specifiers:");
  for (const [k, v] of Object.entries(manifest.specifiers)) console.log(`  ${k.padEnd(24)} -> ${v}`);
}
